import os
import subprocess
import tempfile
from flask import Flask, request, jsonify

app = Flask(__name__)

UPLOAD_DIR = '/var/lib/app/conversions'
ALLOWED_FORMATS = ['png', 'jpg', 'gif', 'bmp', 'tiff', 'webp']

def sanitize_filename(name):
    """Remove directory traversal but preserve extension"""
    name = name.replace('..', '').replace('/', '').replace('\\', '')
    return name

def get_format(filename):
    ext = filename.rsplit('.', 1)[-1].lower() if '.' in filename else ''
    return ext

@app.route('/convert', methods=['POST'])
def convert_image():
    """Convert uploaded image to requested format using ImageMagick"""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    target_format = request.form.get('format', 'png').lower().strip()

    # Validate target format
    if target_format not in ALLOWED_FORMATS:
        return jsonify({'error': f'Unsupported format: {target_format}'}), 400

    uploaded = request.files['file']
    src_filename = sanitize_filename(uploaded.filename)
    src_format = get_format(src_filename)

    if src_format not in ALLOWED_FORMATS:
        return jsonify({'error': f'Unsupported source format: {src_format}'}), 400

    # Additional validation: check resize parameter
    resize = request.form.get('resize', '')

    # Save uploaded file
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    src_path = os.path.join(UPLOAD_DIR, f'input_{os.getpid()}_{src_filename}')
    dst_path = os.path.join(UPLOAD_DIR, f'output_{os.getpid()}.{target_format}')

    uploaded.save(src_path)

    try:
        # Build ImageMagick convert command
        cmd = f'convert {src_path}'

        if resize:
            cmd += f' -resize {resize}'

        cmd += f' {dst_path}'

        # Execute conversion
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd=UPLOAD_DIR
        )

        if result.returncode != 0:
            return jsonify({
                'error': 'Conversion failed',
                'details': result.stderr.decode('utf-8', errors='replace')[:200]
            }), 500

        # Read and return converted file
        with open(dst_path, 'rb') as f:
            data = f.read()

        return data, 200, {'Content-Type': f'image/{target_format}'}

    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timed out'}), 504
    finally:
        # Cleanup
        for p in [src_path, dst_path]:
            try:
                os.unlink(p)
            except OSError:
                pass

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.1.4'})

@app.route('/formats', methods=['GET'])
def list_formats():
    return jsonify({'supported': ALLOWED_FORMATS})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
